"""Minimal PDF text extractor (zlib + Tj/TJ operators), standard library only.
Used to read the two sources of design condition C5 at source, because no
pdftotext, pypdf or pymupdf is installed in this container.
"""
import re
import sys
import zlib


def extract(path):
    data = open(path, "rb").read()
    out = []
    for m in re.finditer(rb"stream\r?\n", data):
        start = m.end()
        end = data.find(b"endstream", start)
        if end < 0:
            continue
        chunk = data[start:end]
        try:
            txt = zlib.decompress(chunk)
        except Exception:
            continue
        pieces = []
        # (string) Tj   and   [ (a) -1 (b) ] TJ
        for tm in re.finditer(rb"\((?:\\.|[^()\\])*\)", txt):
            s = tm.group(0)[1:-1]
            s = s.replace(b"\\(", b"(").replace(b"\\)", b")")
            s = s.replace(b"\\\\", b"\\")
            pieces.append(s.decode("latin-1"))
        if pieces:
            out.append(" ".join(pieces))
    return "\n".join(out)


if __name__ == "__main__":
    path = sys.argv[1]
    text = extract(path)
    print("EXTRACTED_CHARS %d" % len(text))
    if len(sys.argv) > 2:
        pats = sys.argv[2:]
        for pat in pats:
            print("\n#### matches for %r" % pat)
            for m in re.finditer(pat, text, re.I):
                lo = max(0, m.start() - 420)
                hi = min(len(text), m.end() + 420)
                seg = " ".join(text[lo:hi].split())
                print("   ...%s...\n" % seg)
    else:
        print(text[:3000])
